'use client';

import { useEffect, useState } from 'react';

export default function AdSenseDebugPage() {
  const [testResults, setTestResults] = useState<Record<string, unknown>>({});

  useEffect(() => {
    const runDiagnostics = async () => {
      const results: Record<string, unknown> = {};

      // 1. Check environment variables
      results.publisherId = process.env.NEXT_PUBLIC_ADSENSE_PUBLISHER_ID || 'NOT SET';
      results.customerId = process.env.NEXT_PUBLIC_ADSENSE_CUSTOMER_ID || 'NOT SET';

      // 2. Check if adsbygoogle is available
      results.adsByGoogleLoaded = (window as any).adsbygoogle !== undefined;

      // 3. Check browser info
      results.userAgent = navigator.userAgent;
      results.hostname = window.location.hostname;
      results.protocol = window.location.protocol;

      // 4. Check for ad blockers
      const testAdScript = document.createElement('script');
      testAdScript.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js';
      testAdScript.async = true;
      
      let adBlockerDetected = false;
      testAdScript.onerror = () => {
        adBlockerDetected = true;
      };
      
      // Don't actually add it, just test
      results.adBlockerDetected = adBlockerDetected;

      // 5. Network test
      try {
        const response = await fetch(
          'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js',
          { method: 'HEAD', mode: 'no-cors' }
        );
        results.networkTest = 'Script is reachable';
        results.networkStatus = response.status;
      } catch (error) {
        results.networkTest = (error as any)?.message ?? String(error);
      }

      // 6. CSP check
      const cspMeta = document.querySelector('meta[http-equiv="Content-Security-Policy"]');
      results.cspFound = !!cspMeta;
      results.cspContent = cspMeta?.getAttribute('content') || 'Not found';

      setTestResults(results);
    };

    runDiagnostics();
  }, []);

  return (
    <div className="p-5 font-mono text-sm">
      <h1 className="text-xl font-semibold mb-4">🔍 AdSense Debug Diagnostics</h1>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">📋 Environment Variables</h2>
        <pre className="bg-gray-100 p-2.5 rounded">
          {JSON.stringify(
            {
              publisherId: testResults.publisherId,
              customerId: testResults.customerId,
            },
            null,
            2
          )}
        </pre>
      </section>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">🌐 Browser & Network</h2>
        <pre className="bg-gray-100 p-2.5 rounded">
          {JSON.stringify(
            {
              hostname: testResults.hostname,
              protocol: testResults.protocol,
              adsByGoogleLoaded: testResults.adsByGoogleLoaded,
              networkTest: testResults.networkTest,
              networkStatus: testResults.networkStatus,
            },
            null,
            2
          )}
        </pre>
      </section>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">🚫 Ad Blocker Detection</h2>
        <div
          className={`p-2.5 rounded ${testResults.adBlockerDetected ? 'bg-red-100' : 'bg-green-100'}`}
        >
          {testResults.adBlockerDetected ? '❌ Ad blocker DETECTED' : '✅ No ad blocker detected'}
        </div>
      </section>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">🔒 Content Security Policy</h2>
        <pre className="bg-gray-100 p-2.5 rounded">
          {JSON.stringify(
            {
              cspFound: testResults.cspFound,
              cspContent: testResults.cspContent,
            },
            null,
            2
          )}
        </pre>
      </section>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">📊 Full Debug Info</h2>
        <pre className="bg-gray-100 p-2.5 rounded">
          {JSON.stringify(testResults, null, 2)}
        </pre>
      </section>

      <section className="mb-4">
        <h2 className="text-lg font-medium mb-2">💡 Troubleshooting Steps</h2>
        <ol className="list-decimal list-inside space-y-1">
          <li>Check if publisherId is set correctly (should start with 'pub-')</li>
          <li>Disable ad blockers and refresh</li>
          <li>Check Network tab in DevTools for script loading status</li>
          <li>Verify AdSense account is approved at adsense.google.com</li>
          <li>Check browser console for CSP or CORS errors</li>
          <li>Restart Next.js dev server: <code>npm run dev</code></li>
          <li>Clear .next cache: <code>rm -rf .next</code></li>
        </ol>
      </section>

      <section>
        <h2 className="text-lg font-medium mb-2">📝 Copy This Debug Info</h2>
        <label htmlFor="debugCopy" className="sr-only">Debug Info</label>
        <textarea
          id="debugCopy"
          readOnly
          value={JSON.stringify(
            {
              timestamp: new Date().toISOString(),
              ...testResults,
            },
            null,
            2
          )}
          className="w-full h-48 p-2.5 font-mono text-sm"
        />
      </section>
    </div>
  );
}

import { connectDB, hasMongoDBConfig } from "@/lib/db";
import { requireAdminSession } from "@/lib/admin-auth";
import { revalidatePath } from "next/cache";
import Product from "@/models/Product";
import { getProducts } from "@/lib/products";
import fs from "fs/promises";
import path from "path";

// Helper to create filesystem-friendly slugs
function slugify(text) {
  return String(text)
    .normalize("NFD")
    .replace(/[�--]/g, "")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-_]/g, "")
    .replace(/--+/g, "-");
}

export async function GET(request) {
  try {
    const { searchParams } = new URL(request.url);
    const slug = searchParams.get('slug');

    if (slug) {
      // If there's no MongoDB configured, return a safe sample product
      if (!hasMongoDBConfig()) {
        const prettyTitle = slug.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
        const sample = {
          _id: `sample-${Date.now()}`,
          title: prettyTitle,
          slug,
          image: '/uploads/products/product-1781726301171-iephjg.jpg',
          price: 'USD $19.99',
          rating: 4.5,
          affiliateLink: '#',
          affiliateLinks: {},
          category: 'Smart Home',
          description: 'Sample product (MongoDB not configured). Replace with real product data when DB is available.',
          clicks: 0,
          conversions: 0,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };

        return Response.json(sample);
      }

      // Fetch single product by slug from DB
      try {
        await connectDB();
      } catch (connErr) {
        // If connection fails, return the sample as fallback
        const prettyTitle = slug.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
        const sample = {
          _id: `sample-${Date.now()}`,
          title: prettyTitle,
          slug,
          image: '/uploads/products/product-1781726301171-iephjg.jpg',
          price: 'USD $19.99',
          rating: 4.5,
          affiliateLink: '#',
          affiliateLinks: {},
          category: 'Smart Home',
          description: 'Sample product (MongoDB connection failed). Replace with real product data when DB is available.',
          clicks: 0,
          conversions: 0,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };

        return Response.json(sample);
      }

      const product = await Product.findOne({ slug }).lean();
      if (!product) {
        return Response.json({ error: 'Product not found' }, { status: 404 });
      }

      // Convert to plain serializable object
      let affiliateLinks = {};
      if (product.affiliateLinks) {
        if (product.affiliateLinks instanceof Map) {
          affiliateLinks = Object.fromEntries(product.affiliateLinks);
        } else {
          affiliateLinks = product.affiliateLinks;
        }
      }

      const serializedProduct = {
        _id: product._id.toString(),
        title: product.title,
        slug: product.slug,
        image: product.image || null,
        images: Array.isArray(product.images) ? product.images : (product.images ? [product.images] : []),
        price: product.price || null,
        rating: product.rating || 4.5,
        affiliateLink: product.affiliateLink || null,
        affiliateLinks: affiliateLinks,
        category: product.category || null,
        description: product.description || null,
        clicks: product.clicks || 0,
        conversions: product.conversions || 0,
        createdAt: product.createdAt?.toISOString() || null,
        updatedAt: product.updatedAt?.toISOString() || null,
      };

      return Response.json(serializedProduct);
    }

    // Fetch all products
    const products = await getProducts({ fallbackOnError: false });
    return Response.json(products);
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}

export async function POST(req) {
  const unauthorized = await requireAdminSession();
  if (unauthorized) return unauthorized;

  try {
    await connectDB();
    const data = await req.json();

    // Create slug from title
    const slug = data.title
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/[^\w-]/g, "");

    // Handle base64 image uploads (if provided)
    const images = Array.isArray(data.images) ? data.images : [];
    const uploadDir = path.join(process.cwd(), "public", "uploads", "products");
    await fs.mkdir(uploadDir, { recursive: true });

    const savedImageUrls = [];
    for (const [index, base64Image] of images.entries()) {
      if (typeof base64Image !== "string") continue;

      const matches = base64Image.match(/^data:([A-Za-z-+\/.]+);base64,(.+)$/);
      if (!matches || matches.length !== 3) {
        console.warn("Invalid base64 image format encountered, skipping.");
        continue;
      }

      const imageType = matches[1].split("/")[1] || "png";
      const imageData = Buffer.from(matches[2], "base64");

      const baseFilename = slugify(data.title || "product").slice(0, 80);
      const filename = `${baseFilename}-${Date.now()}-${index}.${imageType}`;
      const filePath = path.join(uploadDir, filename);

      await fs.writeFile(filePath, imageData);
      savedImageUrls.push(`/uploads/products/${filename}`);
    }

    const product = await Product.create({
      ...data,
      slug: slug,
      image: savedImageUrls[0] || data.image || '',
      images: savedImageUrls,
    });

    // Convert to plain serializable object
    let createdAffiliateLinks = {};
    if (product.affiliateLinks) {
      if (product.affiliateLinks instanceof Map) createdAffiliateLinks = Object.fromEntries(product.affiliateLinks);
      else createdAffiliateLinks = product.affiliateLinks;
    }

    const serializedProduct = {
      _id: product._id.toString(),
      title: product.title,
      slug: product.slug,
      image: product.image || null,
      price: product.price || null,
      rating: product.rating || 4.5,
      affiliateLink: product.affiliateLink || null,
      affiliateLinks: createdAffiliateLinks,
      category: product.category || null,
      description: product.description || null,
      clicks: product.clicks || 0,
      conversions: product.conversions || 0,
      createdAt: product.createdAt?.toISOString() || null,
      updatedAt: product.updatedAt?.toISOString() || null,
    };

    revalidatePath("/");
    revalidatePath("/blog");
    revalidatePath("/products");
    try {
      revalidatePath(`/products/${product.slug}`);
    } catch (_) {}

    // Include saved images in the serialized response
    serializedProduct.images = Array.isArray(product.images) ? product.images : (product.images ? [product.images] : []);

    return Response.json(serializedProduct);
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}

import fs from "fs";
import path from "path";
import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { ADMIN_SESSION_COOKIE, verifySessionToken } from "@/lib/admin-session";
import { saveBufferToStorage } from "@/lib/storage";

const SETTINGS_PATH = path.join(process.cwd(), "data", "site-settings.json");
const PUBLIC_DIR = path.join(process.cwd(), "public");

function parseDataUrl(dataUrl) {
  const match = typeof dataUrl === "string" && dataUrl.match(/^data:(.+);base64,(.+)$/);
  if (!match) return null;
  return { mime: match[1], base64: match[2] };
}

export async function GET() {
  try {
    const raw = fs.readFileSync(SETTINGS_PATH, "utf8");
    const settings = JSON.parse(raw);
    return NextResponse.json(settings);
  } catch (err) {
    const fallback = { subtitle: "Make your home smarter", logo: "/logo.png", favicon: "/favicon.ico" };
    return NextResponse.json(fallback);
  }
}

export async function POST(request) {
  // Protect POST: require valid admin session cookie
  try {
    const cookieStore = await cookies();
    const tokenCookie = cookieStore.get(ADMIN_SESSION_COOKIE);
    const token = tokenCookie && tokenCookie.value ? tokenCookie.value : null;
    const session = token ? verifySessionToken(token) : null;
    if (!session) {
      return NextResponse.json({ success: false, error: "not_authorized" }, { status: 401 });
    }
  } catch (e) {
    return NextResponse.json({ success: false, error: "not_authorized" }, { status: 401 });
  }

  try {
    const body = await request.json();
    const { title = "", subtitle = "", logoBase64, faviconBase64, seo } = body || {};

    // Load existing settings if present
    let existing = {};
    try {
      existing = JSON.parse(fs.readFileSync(SETTINGS_PATH, "utf8"));
    } catch (e) {
      existing = {};
    }

    const newSettings = { ...existing, title: title || existing.title || "", subtitle: subtitle || existing.subtitle || "" };
    if (seo) {
      newSettings.seo = { ...(existing.seo || {}), ...seo };
    }

    // Ensure public dir exists
    try {
      fs.mkdirSync(PUBLIC_DIR, { recursive: true });
    } catch (e) {}

    if (logoBase64) {
      const parsed = parseDataUrl(logoBase64);
      let ext = "png";
      let buffer;
      let mime = "image/png";
      if (parsed) {
        mime = parsed.mime;
        ext = parsed.mime.split("/")[1] || "png";
        if (ext === "jpeg") ext = "jpg";
        buffer = Buffer.from(parsed.base64, "base64");
      } else {
        buffer = Buffer.from(logoBase64, "base64");
      }

      const logoFilename = `logo.${ext}`;
      try {
        const res = await saveBufferToStorage(buffer, logoFilename, mime);
        newSettings.logo = res.url;
      } catch (e) {
        // Fallback to local write
        fs.writeFileSync(path.join(PUBLIC_DIR, logoFilename), buffer);
        newSettings.logo = `/${logoFilename}`;
      }
    }

    if (faviconBase64) {
      const parsed = parseDataUrl(faviconBase64);
      let ext = "ico";
      let buffer;
      let mime = "image/x-icon";
      if (parsed) {
        mime = parsed.mime;
        ext = parsed.mime.split("/")[1] || "ico";
        if (ext === "jpeg") ext = "jpg";
        buffer = Buffer.from(parsed.base64, "base64");
      } else {
        buffer = Buffer.from(faviconBase64, "base64");
      }

      const favFilename = `favicon.${ext}`;
      try {
        const res = await saveBufferToStorage(buffer, favFilename, mime);
        newSettings.favicon = res.url;
      } catch (e) {
        fs.writeFileSync(path.join(PUBLIC_DIR, favFilename), buffer);
        newSettings.favicon = `/${favFilename}`;
      }
    }

    // Persist settings file
    try {
      fs.mkdirSync(path.dirname(SETTINGS_PATH), { recursive: true });
      fs.writeFileSync(SETTINGS_PATH, JSON.stringify(newSettings, null, 2), "utf8");
    } catch (e) {
      console.error("Failed writing settings file:", e);
    }

    return NextResponse.json({ success: true, settings: newSettings });
  } catch (err) {
    console.error(err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

import Link from "next/link";
import type { ReactNode } from "react";
import { getBlogArticle, getLatestArticles } from "@/lib/blog";
import { connectDB } from "@/lib/db";
import Blog from "@/models/Blog";
import { SITE_NAME, SITE_URL } from "@/lib/site";
import { notFound } from "next/navigation";

export const dynamic = "force-dynamic";

type BlogArticleDoc = {
  _id?: { toString?: () => string };
  slug?: string;
  title?: string;
  description?: string;
  excerpt?: string;
  content?: string;
  category?: string;
  author?: string;
  date?: string;
  createdAt?: Date;
  readTime?: number;
  images?: string[];
  imageUrls?: string[];
  tags?: string[];
};

type RelatedArticle = {
  id?: string;
  slug?: string;
  title?: string;
  excerpt?: string;
  readTime?: number;
};

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;

  // Try DB first, fallback to static articles
  try {
    await connectDB();
    const entry = (await Blog.findOne({ slug, published: true }).lean()) as BlogArticleDoc | null;
    if (entry) {
      return {
        title: `${entry.title} | ${SITE_NAME}`,
        description: entry.description || entry.excerpt || "",
        keywords: (entry.tags || []).join(", "),
        alternates: {
          canonical: `${SITE_URL}/blog/${entry.slug}`,
        },
        openGraph: {
          title: entry.title,
          description: entry.description || entry.excerpt || "",
          url: `${SITE_URL}/blog/${entry.slug}`,
          type: "article",
          publishedTime: entry.createdAt,
          authors: [entry.author || SITE_NAME],
          tags: entry.tags || [],
        },
        article: {
          publishedTime: entry.createdAt,
          authors: [entry.author || SITE_NAME],
          tags: entry.tags || [],
        },
      };
    }
  } catch {
    // ignore DB errors and fallback to static
  }

  const article = getBlogArticle(slug);

  if (!article) {
    return {
      title: "Article Not Found",
      description: "The article you're looking for doesn't exist.",
    };
  }

  const tags = article.tags ?? [];

  return {
    title: `${article.title} | ${SITE_NAME}`,
    description: article.excerpt,
    keywords: tags.join(", "),
    alternates: {
      canonical: `${SITE_URL}/blog/${article.slug}`,
    },
    openGraph: {
      title: article.title,
      description: article.excerpt,
      url: `${SITE_URL}/blog/${article.slug}`,
      type: "article",
      publishedTime: article.date,
      authors: [article.author],
      tags,
    },
    article: {
      publishedTime: article.date,
      authors: [article.author],
      tags,
    },
  };
}

export default async function BlogPost({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;

  let article: BlogArticleDoc | null = null;
  try {
    await connectDB();
    article = (await Blog.findOne({ slug, published: true }).lean()) as BlogArticleDoc | null;
  } catch {
    // ignore DB errors and fallback to static list
  }

  if (!article) {
    article = getBlogArticle(slug);
    if (!article) notFound();
  }

  // Related articles: attempt DB, otherwise fallback to static
  const relatedArticles = (await (async () => {
    try {
      if (typeof article._id !== "undefined") {
        const latest = (await Blog.find({ published: true }).sort({ createdAt: -1 }).limit(4).lean()) as BlogArticleDoc[];
        return latest.map((a) => ({ id: a._id?.toString?.() ?? String(a._id), slug: a.slug, title: a.title, excerpt: a.description || "", readTime: a.readTime || 5 }));
      }
    } catch {
      // fallback
    }
    return getLatestArticles(3);
  })());
  const articleTags = article.tags ?? [];
  const articleDate =
    article.createdAt?.toISOString?.() || article.date || new Date().toISOString();
  const articleAuthor = article.author || SITE_NAME;
  const articleReadTime = article.readTime || 5;
  const articleImages =
    article.images?.length ? article.images : article.imageUrls ?? [];

  // Get author initials for avatar
  const authorInitials = articleAuthor
    .split(" ")
    .map((w: string) => w[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  return (
    <div className="min-h-screen bg-white">
      {/* Main Article Area */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-4 pt-8 pb-12 sm:pt-12 sm:pb-16">
        {/* Article Title */}
        <h1 className="text-[2.5rem] sm:text-[3rem] leading-tight font-bold text-gray-900 mb-4 tracking-tight">
          {article.title}
        </h1>

        {/* Subtitle / Excerpt */}
        {(article.description || article.excerpt) && (
          <p className="text-lg sm:text-xl text-gray-700 mb-6 leading-relaxed">
            {article.description || article.excerpt}
          </p>
        )}

        {/* Author Info */}
        <div className="flex items-center gap-3 mb-8 pb-8 border-b border-gray-200">
          <div className="w-10 h-10 rounded-full bg-gray-800 text-white flex items-center justify-center text-sm font-bold shrink-0">
            {authorInitials}
          </div>
          <div>
            <p className="text-sm font-semibold text-gray-900">By {articleAuthor}</p>
            <p className="text-xs text-gray-500">
              Updated {new Date(articleDate).toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
              })} • {articleReadTime} min read
            </p>
          </div>
        </div>

        {/* Hero Image (first image) */}
        {articleImages.length > 0 && (
          <figure className="mb-8">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={articleImages[0]}
                alt={article.title}
                className="w-full h-auto rounded-sm object-cover `max-h-[520px]`"
              />
            </figure>
        )}

        {/* Article Content */}
        <article className="prose prose-lg max-w-none">
          {(() => {
            const content = article.content || "";
            const paragraphs = content
              .split(/\n\s*\n/)
              .map((p: string) => p.trim())
              .filter(Boolean);
            const images = (articleImages.length > 1
              ? articleImages.slice(1)
              : []) as string[];
            const blocks: ReactNode[] = [];
            let imageIndex = 0;

            const renderLines = (para: string, keyPrefix: string) => {
              const lines = para.split("\n").map((l: string) => l.trim()).filter(Boolean);
              if (lines.length === 1) {
                const line = lines[0];
                if (line.startsWith("## ")) {
                  return (
                    <h2 key={`${keyPrefix}-h2`} className="text-3xl font-bold mt-10 mb-4 text-gray-900 leading-tight">
                      {line.replace(/^##\s*/, "")}
                    </h2>
                  );
                }
                if (line.startsWith("### ")) {
                  return (
                    <h3 key={`${keyPrefix}-h3`} className="text-2xl font-bold mt-8 mb-3 text-gray-900">
                      {line.replace(/^###\s*/, "")}
                    </h3>
                  );
                }
                // Handle bold paragraphs
                if (line.startsWith("**") && line.endsWith("**")) {
                  return (
                    <p key={`${keyPrefix}-bold`} className="text-gray-800 mb-4 font-semibold leading-relaxed">
                      {line.replace(/^\*\*/, "").replace(/\*\*$/, "")}
                    </p>
                  );
                }
                // Handle lines with inline bold
                if (line.includes("**")) {
                  const parts = line.split(/(\*\*[^*]+\*\*)/g);
                  return (
                    <p key={`${keyPrefix}-mixed`} className="text-gray-800 mb-4 leading-relaxed">
                      {parts.map((part, idx) => {
                        if (part.startsWith("**") && part.endsWith("**")) {
                          return <strong key={idx}>{part.replace(/^\*\*/, "").replace(/\*\*$/, "")}</strong>;
                        }
                        return part;
                      })}
                    </p>
                  );
                }
                // Handle italic text
                if (line.startsWith("*") && line.endsWith("*") && !line.startsWith("**")) {
                  return (
                    <p key={`${keyPrefix}-italic`} className="text-gray-600 mb-4 italic leading-relaxed">
                      {line.replace(/^\*/, "").replace(/\*$/, "")}
                    </p>
                  );
                }
                return (
                  <p key={`${keyPrefix}-p`} className="text-gray-800 mb-4 leading-relaxed">
                    {line}
                  </p>
                );
              }

              // Multiple lines - check if it's a list
              if (lines.every((l: string) => l.startsWith("- "))) {
                return (
                  <ul key={`${keyPrefix}-ul`} className="list-disc pl-6 mb-4 text-gray-800 space-y-1">
                    {lines.map((l: string, idx: number) => (
                      <li key={idx} className="leading-relaxed">{l.replace(/^-\s*/, "")}</li>
                    ))}
                  </ul>
                );
              }

              // Check if lines start with numbers (ordered list)
              if (lines.every((l: string) => /^\d+[\.\)]\s/.test(l))) {
                return (
                  <ol key={`${keyPrefix}-ol`} className="list-decimal pl-6 mb-4 text-gray-800 space-y-1">
                    {lines.map((l: string, idx: number) => (
                      <li key={idx} className="leading-relaxed">{l.replace(/^\d+[\.\)]\s*/, "")}</li>
                    ))}
                  </ol>
                );
              }

              // Join multi-line paragraphs
              return (
                <p key={`${keyPrefix}-pjoin`} className="text-gray-800 mb-4 leading-relaxed">
                  {lines.join(" ")}
                </p>
              );
            };

            for (let i = 0; i < paragraphs.length; i++) {
              const para = paragraphs[i];

              blocks.push(
                <div key={`para-${i}`}>
                  {renderLines(para, `para-${i}`)}
                </div>
              );

              // Insert an image after every 2-3 paragraphs (spread images naturally)
              if (images.length > 0 && imageIndex < images.length) {
                const shouldInsert =
                  (i > 0 && i % 3 === 0) ||
                  (i === paragraphs.length - 1 && imageIndex < images.length);
                if (shouldInsert) {
                  blocks.push(
                    <figure key={`img-${i}`} className="my-8">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={images[imageIndex]}
                          alt={`${article.title} - image ${imageIndex + 2}`}
                          className="w-full h-auto rounded-sm object-cover"
                          loading="lazy"
                        />
                      </figure>
                  );
                  imageIndex++;
                }
              }
            }

            // Render any remaining images
            while (imageIndex < images.length) {
              blocks.push(
                <figure key={`extra-img-${imageIndex}`} className="my-8">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={images[imageIndex]}
                    alt={`${article.title} - image ${imageIndex + 2}`}
                    className="w-full h-auto rounded-sm object-cover"
                    loading="lazy"
                  />
                </figure>
              );
              imageIndex++;
            }

            return blocks;
          })()}
        </article>

        {/* Sponsor Notice */}
        <div className="mt-12 pt-8 border-t border-gray-200">
          <p className="text-sm text-gray-500 italic">
            This article is sponsored by the{" "}
            <Link href="#" className="text-teal-600 hover:text-teal-700 not-italic font-medium">
              {SITE_NAME}
            </Link>
            .
          </p>
        </div>

        {/* Tags */}
        {articleTags.length > 0 && (
          <div className="mt-8 pt-6 border-t border-gray-200">
            <div className="flex flex-wrap gap-2">
              {articleTags.map((tag: string) => (
                <Link
                  key={tag}
                  href={`/category/${encodeURIComponent(tag)}`}
                  className="bg-gray-100 text-gray-700 px-3 py-1 rounded-full text-sm hover:bg-gray-200 transition-colors"
                >
                  #{tag}
                </Link>
              ))}
            </div>
          </div>
        )}

        {/* Author Bio Box */}
        <div className="mt-10 p-6 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex items-start gap-4">
            <div className="w-14 h-14 rounded-full bg-gray-800 text-white flex items-center justify-center text-lg font-bold shrink-0">
              {authorInitials}
            </div>
            <div>
              <p className="font-bold text-gray-900 text-lg">{articleAuthor}</p>
              <p className="text-gray-600 text-sm mt-1 leading-relaxed">
                Expert contributor to {SITE_NAME} with extensive experience in smart home technology and product reviews.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
